// A prerequisite route connects the eight stable Section 2 lesson addresses.
// All examples and short checks are authored teaching material, not past papers.
const ids = (requirement, ...numbers) => numbers.map(number => `S2.${String(requirement).padStart(2, '0')}.A${String(number).padStart(2, '0')}`);
const table = (headers, rows) => ({ headers, rows });
const step = (title, body, extra = {}) => ({ title, body, ...extra });
const worked = (title, setup, steps, conclusion) => ({ title, setup, steps, conclusion });
const stimulus = (title, items, grid) => ({ title, items, ...(grid ? { table: grid } : {}) });
const figure = (name, alt, caption) => ({ asset: `/assets/course-v3/section-2/${name}.svg`, alt, caption });

